"""Opt-in round trips with real results generated by the Cystemas fit tests."""

import os
from pathlib import Path
import subprocess
import tempfile
import unittest

import numpy as np
from matplotlib.figure import Figure

from csv_plotter_metadata import read_result_tsv, write_result_tsv
import test_extended_tsv
from test_metadata_presentation import load_presentation, pane_text


class CystemasIntegrationTests(unittest.TestCase):
    def run_cystemas(self, executable, root, env):
        result = subprocess.run([str(executable)], cwd=root, env=env,
                                timeout=120, capture_output=True, text=True)
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

    @unittest.skipUnless(os.environ.get("CY_TEST_FIT_EXE"),
                         "set CY_TEST_FIT_EXE to a HDF5-enabled cy_fit_test")
    def test_real_simulation_and_fit_roundtrip(self):
        executable = Path(os.environ["CY_TEST_FIT_EXE"]).resolve(strict=True)
        checks = test_extended_tsv.ExtendedTsvTests()
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            env = os.environ.copy()
            env.pop("CY_TEST_IMPORT_TSV_DIR", None)
            env["CY_TEST_EXPORT_TSV_DIR"] = directory
            self.run_cystemas(executable, root, env)
            for name in ("simulation", "fit"):
                with self.subTest(result=name):
                    hdf5 = load_presentation(root / f"{name}.h5")
                    tsv = load_presentation(root / f"{name}_complete.tsv")
                    checks.assert_metadata_equal(tsv["metadata_rows"], hdf5["metadata_rows"])
                    checks.assert_tables_equal(
                        (tsv["data_frame"], tsv["column_registry"]),
                        (hdf5["data_frame"], hdf5["column_registry"]))
                    self.assertEqual(pane_text(tsv), pane_text(hdf5))
                    variant, rows, frame, registry = read_result_tsv(root / f"{name}_complete.tsv")
                    self.assertEqual(variant, "combined")
                    meta_variant, meta_rows, meta_frame, meta_registry = read_result_tsv(
                        root / f"{name}_metadata.tsv")
                    self.assertEqual(meta_variant, "metadata_only")
                    checks.assert_metadata_equal(meta_rows, rows)
                    self.assertTrue(meta_frame.empty)
                    _, _, time_frame, time_registry = read_result_tsv(root / f"{name}_timeseries.tsv")
                    checks.assert_tables_equal((frame, registry), (time_frame, time_registry))
                    for converted_path in (root / f"{name}_converted.h5",
                                           root / f"{name}_from_hdf5.tsv"):
                        converted = load_presentation(converted_path)
                        checks.assert_metadata_equal(converted["metadata_rows"], rows)
                        checks.assert_tables_equal(
                            (converted["data_frame"], converted["column_registry"]), (frame, registry))
                        self.assertEqual(pane_text(converted), pane_text(tsv))
                    converted_meta = load_presentation(root / f"{name}_metadata.h5")
                    standalone_meta = load_presentation(root / f"{name}_metadata.tsv")
                    checks.assert_metadata_equal(converted_meta["metadata_rows"], meta_rows)
                    self.assertTrue(converted_meta["data_frame"].empty)
                    self.assertEqual(pane_text(converted_meta), pane_text(standalone_meta))
                    signals = tsv["named_value_by_display_name"]
                    self.assertEqual(signals, hdf5["named_value_by_display_name"])
                    self.assertIn("parameters.gain", signals)
                    self.assertIn("initial_states.x", signals)
                    if name == "fit":
                        self.assertIn("fit_initial_states.x", signals)
                        self.assertAlmostEqual(signals["fit_parameters.gain"]["value"], 2.0)
                    else:
                        self.assertEqual(signals["initial_states.x"]["value"], .25)
                    for signal, entry in signals.items():
                        for state in (tsv, hdf5):
                            state["styles"] = {signal: "solid"}
                            state["colors"] = {signal: "blue"}
                            axes = Figure().add_subplot(111)
                            state["add_plot"](signal, axes)
                            expected = np.full(len(frame), entry["value"])
                            np.testing.assert_array_equal(axes.lines[0].get_ydata(), expected)
                            np.testing.assert_array_equal(axes.lines[0].get_xdata(), state["x_data"])
                            np.testing.assert_array_equal(state["spectrum_signal_values"](signal), expected)
                    for suffix, kind, values, table, columns in (
                            ("python", variant, rows, frame, registry),
                            ("python_metadata", meta_variant, meta_rows, meta_frame, meta_registry)):
                        path = root / f"{name}_{suffix}.tsv"
                        write_result_tsv(path, kind, values, table, columns)
                        result_kind, result_rows, result_frame, result_columns = read_result_tsv(path)
                        self.assertEqual(result_kind, kind)
                        checks.assert_metadata_equal(result_rows, values)
                        checks.assert_tables_equal((result_frame, result_columns), (table, columns))
            env.pop("CY_TEST_EXPORT_TSV_DIR")
            env["CY_TEST_IMPORT_TSV_DIR"] = directory
            verifier = os.environ.get("CY_TEST_FIT_EXE_NO_HDF5")
            self.run_cystemas(executable, root, env)
            if verifier:
                self.run_cystemas(Path(verifier).resolve(strict=True), root, env)


if __name__ == "__main__":
    unittest.main()
